  /** Ranked: risk levels dropped (desc), then cost delta (asc). */
  recommendations: Recommendation[]
}

export interface RiskRow {
  line: BomLine
  risk: LineRisk
}

export const initialJobState: JobState = {
  jobId: null,
  mode: null,
  stage: null,
  lastEventId: 0,
  runs: {},
  runOrder: [],
