    const ab = link(a, b)
    const ba = link(b, a)
    a.addEventListener('camera-change', ab)
    b.addEventListener('camera-change', ba)
    return () => {
      a.removeEventListener('camera-change', ab)
      b.removeEventListener('camera-change', ba)
    }
  }, [a, b])
